LABEL = {'draft': 'CONSULTA', 'opcion': 'OPCION', 'hold': 'HOLD', 'confirmed': 'CONFIRMADA', 'pre_checkin': 'PRE_CHECKIN', 'checked_in': 'CHECKIN', 'checked_out': 'CHECKOUT', 'closed': 'CERRADA', 'cancelled': 'CANCELADA', 'no_show': 'NO_SHOW'}
for order in records:
    vals = {}
    unit = order.x_hotel_unit_id
    if not unit:
        tmpls = order.order_line.mapped('product_id.product_tmpl_id')
        if tmpls:
            unit = UNIT.search([('x_product_tmpl_id', 'in', tmpls.ids)], limit=1)
            if unit:
                vals['x_hotel_unit_id'] = unit.id
    if unit and not order.x_hotel_property_id:
        vals['x_hotel_property_id'] = unit.x_property_id.id
    status = order.x_reservation_status or 'draft'
    if order.state == 'sale' and status in ('draft', 'opcion', 'hold'):
        # Confirmación comercial por fuera del flujo HOTEL v1: se valida como CONFIRMADA (bloquea o rechaza)
        status = 'confirmed'
        vals['x_reservation_status'] = 'confirmed'
    if status == 'hold' and not order.x_hold_expires:
        hours = unit.x_property_id.x_hold_hours or 2.0
        vals['x_hold_expires'] = now + datetime.timedelta(hours=hours)
        vals['x_hold_expired'] = False
    if vals:
        order.sudo().write(vals)
    if not unit or status not in BLOCKING + ASKING:
        continue
    ci = order.x_checkin
    co = order.x_checkout
    if not ci or not co:
        if status in BLOCKING:
            raise UserError('HOTEL: la reserva %s necesita check-in y check-out para estado %s.' % (order.name, LABEL.get(status)))
        continue
    if co <= ci:
        raise UserError('HOTEL: check-out debe ser posterior a check-in (%s).' % order.name)
    # Conjunto de conflicto: hojas físicas de la unidad + todas las unidades que contienen alguna de esas hojas
    leaves = UNIT.browse()
    frontier = unit
    while frontier:
        nochild = frontier.filtered(lambda u: not u.x_child_ids)
        leaves |= nochild
        frontier = (frontier - nochild).mapped('x_child_ids') - leaves
    conflict = leaves
    frontier = leaves
    while frontier:
        nxt = frontier.mapped('x_parent_ids') - conflict
        conflict |= nxt
        frontier = nxt
    conflict |= unit
    if status in BLOCKING:
        # Bloqueo de fila: serializa solicitudes concurrentes sobre unidades relacionadas
        conflict.write({'x_lock_touch': now})
        guests = (order.x_num_adults or 0) + (order.x_num_children or 0)
        cap = unit.x_cap_comercial or 0
        if cap and guests > cap:
            if unit.x_cap_extra and guests <= unit.x_cap_extra:
                if not order.x_hotel_extra_approved:
                    raise UserError('HOTEL: %s huéspedes supera CAPACIDAD_COMERCIAL %s de %s. Capacidad extraordinaria (%s) REQUIERE APROBACIÓN.' % (guests, cap, unit.x_name, unit.x_cap_extra))
            else:
                raise UserError('HOTEL: %s huéspedes supera la capacidad permitida de %s (comercial %s).' % (guests, unit.x_name, cap))
    dom = [('id', 'not in', order.ids), ('x_hotel_unit_id', 'in', conflict.ids), ('x_checkin', '<', co), ('x_checkout', '>', ci),
           '|', ('x_reservation_status', 'in', ('confirmed', 'pre_checkin', 'checked_in')),
           '&', ('x_reservation_status', '=', 'hold'), ('x_hold_expires', '>', now)]
    clash = SO.search(dom, limit=1)
    reason = False
    if clash:
        extra = ''
        if clash.x_reservation_status == 'hold':
            extra = ' (HOLD vence %s UTC)' % clash.x_hold_expires
        reason = '%s ocupada por %s [%s] %s→%s, estado %s%s' % (clash.x_hotel_unit_id.x_name, clash.name, clash.partner_id.name or '', clash.x_checkin, clash.x_checkout, LABEL.get(clash.x_reservation_status), extra)
    if not reason:
        tmpl_ids = conflict.mapped('x_product_tmpl_id').ids
        if tmpl_ids:
            legacy = SO.search([('id', 'not in', order.ids), ('x_hotel_unit_id', '=', False), ('state', 'in', ('sale', 'done')), ('x_checkin', '<', co), ('x_checkout', '>', ci), ('order_line.product_id.product_tmpl_id', 'in', tmpl_ids)], limit=1)
            if legacy:
                reason = 'reserva legacy %s %s→%s' % (legacy.name, legacy.x_checkin, legacy.x_checkout)
    if not reason:
        prop = unit.x_property_id
        tzname = prop.x_tz or 'America/Bogota'
        cin = prop.x_checkin_time or 15.0
        cout = prop.x_checkout_time or 11.0
        tz = timezone(tzname)
        utc = timezone('UTC')
        st = tz.localize(datetime.datetime(ci.year, ci.month, ci.day, int(cin), int(round((cin % 1) * 60)))).astimezone(utc).replace(tzinfo=None)
        en = tz.localize(datetime.datetime(co.year, co.month, co.day, int(cout), int(round((cout % 1) * 60)))).astimezone(utc).replace(tzinfo=None)
        res = conflict.mapped('x_resource_id')
        if res:
            slots = PS.search([('resource_id', 'in', res.ids), ('start_datetime', '<', en), ('end_datetime', '>', st)])
            slots = slots.filtered(lambda s: not s.x_bloqueo_ref and not s.x_bloqueo_src_id and s.x_hotel_block_kind != 'hold' and s.x_checkin_state != 'cancelled' and not (s.sale_line_id and s.sale_line_id.order_id.x_hotel_unit_id))
            if slots:
                s0 = slots[0]
                reason = 'bloqueo en calendario/OTA (planning.slot %s, %s, %s→%s UTC)' % (s0.id, s0.resource_id.name, s0.start_datetime, s0.end_datetime)
    if status in BLOCKING:
        if reason:
            raise UserError('HOTEL — NO DISPONIBLE: %s no puede pasar a %s del %s al %s. Motivo: %s. No se permite doble reserva.' % (unit.x_name, LABEL.get(status), ci, co, reason))
    else:
        alert = ('ALERTA COMERCIAL: %s no disponible del %s al %s — %s' % (unit.x_name, ci, co, reason)) if reason else False
        if (order.x_hotel_alert or False) != alert:
            order.sudo().write({'x_hotel_alert': alert})
            if alert and clash:
                clash.message_post(body='Solicitud concurrente: %s (%s) pidió %s del %s al %s mientras esta reserva la bloquea.' % (order.name, order.partner_id.name or '', unit.x_name, ci, co), subtype_xmlid='mail.mt_note')

